// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {TimelockController} from "../src/TimelockController.sol";

contract InvMutTest is Test {
    TimelockController c;

    function setUp() public {
        c = new TimelockController(0, new address[](0), new address[](0));
    }

    function testFuzz_property(address account) public {
        // No PROPOSER_ROLE was ever granted to anyone in setUp, so for ANY
        // account the role mapping must report false. The mutant returns
        // true unconditionally.
        assertTrue(!c.hasRole(c.PROPOSER_ROLE(), account));
    }
}
